int LookupMnem(MNEM_TAB *table, const char *string)
{
        while (table->mnem != NULL) {
                if (string && strcmp(string, table->mnem) == 0)
                        return table->value;
                table++;
        }
        return table->value;
}

const char *LookupMnemName(MNEM_TAB *table, const int value)
{
        while (table->mnem != NULL) {
                if (table->value == value)
                        return table->mnem;
                table++;
        }
        return ""; // not found
